entries[132357] = { ["name"] = "Pillars of the Dark Portal", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Critical Strike\n+ 3 Haste\n+ 4 Mastery\nDurability 145 / 145\nClasses: Warlock\nEquip: Demonic Gateway now casts instantly and you can use Demonic Gateways twice before triggering a cooldown.\n\"Corrupted by the demonlord Sargeras, Medivh contacted the orc warlock Gul'dan and together they opened the Dark Portal, allowing the Burning Legion to begin its invasion of Azeroth.\"\nSell Price:" }
entries[132359] = { ["name"] = "The Subjugator's Shackles", ["text"] = "Binds when picked up\nWrist Plate\n8 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 4 Haste\n+ 2 Mastery\nDurability 50 / 50\nSell Price:" }
entries[132360] = { ["name"] = "Petrified Arkhana", ["text"] = "Binds when picked up\nSell Price:" }
entries[132361] = { ["name"] = "Petrified Arkhana", ["text"] = "Artifact Power\nBinds when picked up" }
entries[132365] = { ["name"] = "Shackles of Bryndaor", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Plate\n9 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Mastery\nDurability 70 / 70\nClasses: Death Knight\nEquip: Death Strike refunds 15% of Runic Power spent if it heals you for more than 10% of your maximum health.\n\"For his misdeeds, Bryndaor was charged with guarding the gates of Helheim for eternity.\"\nSell Price:" }
entries[132366] = { ["name"] = "Koltira's Newfound Will", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Critical Strike\n+ 5 Haste\nDurability 70 / 70\nClasses: Death Knight\nEquip: Obliterate deals 10% more damage and has a 15% chance to refund 1 rune. (Proc chance: 15%)\n\"Following the Battle for Light's Hope Chapel, the two comrades parted ways. Thassarian opted to serve his king, while Koltira, former defender of Quel'Thalas, chose to join his people, the blood elves.\"\nSell Price:" }
entries[132367] = { ["name"] = "Service of Gorefiend", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Versatility\n+ 5 Mastery\n+ 6 Leech\nDurability 70 / 70\nClasses: Death Knight\nEquip: Heart Strike reduces the remaining cooldown on Vampiric Blood by 2 seconds.\n\"After his demise, Gorefiend returned as the first death knight and swore allegiance to Orgrim Doomhammer.\"\nSell Price:" }
entries[132368] = { ["name"] = "First Piece of the Band of Farondis", ["text"] = "Quest Item\n\"A broken piece of the Band of Farondis.\"" }
entries[132369] = { ["name"] = "Wilfred's Sigil of Superior Summoning", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Haste\n+ 6 Mastery\n\nPrismatic Socket\n\nClasses: Warlock\nEquip: Each Dreadstalker or Wild Imp you summon reduces the remaining cooldown on Summon Demonic Tyrant by 2 seconds.\n\"Left at home on a crucial day during the Argent Tournament.\"\nSell Price:" }
entries[132370] = { ["name"] = "Salteye Bangle", ["text"] = "Quest Item\n\"A crude ring, suitable for murloc nostrils, lips, and fins.\"" }
entries[132371] = { ["name"] = "Driftwood", ["text"] = "Quest Item\n\"A piece of sun-bleached driftwood.\"" }
entries[132372] = { ["name"] = "Deep Amber Nose Ring", ["text"] = "Quest Item\n\"A crude nose ring with a carved deep amber on the end.\"" }
entries[132373] = { ["name"] = "Azsunite Belly Ring", ["text"] = "Quest Item\n\"A crude belly ring with a carved azsunite on the end.\"" }
entries[132374] = { ["name"] = "Kazzak's Final Curse", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 3 Haste\n+ 4 Mastery\nDurability 70 / 70\nClasses: Warlock\nEquip: Doom deals 5% increased damage for each demon pet you have active.\n\"As the Doom Lord crossed through the Dark Portal to Outland, he left his enemies with a parting gift...\"\nSell Price:" }
entries[132375] = { ["name"] = "Odr, Shawl of the Ymirjar", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Intellect\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Haste\nClasses: Warlock\nEquip: Enemies marked by your Havoc take 15% increased damage from your single target spells.\n\"Found pristine under burnt rubble in the village of Ymirheim.\"\nSell Price:" }
entries[132376] = { ["name"] = "Acherus Drapes", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nBack\n3 Armor\n+3 Strength\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Haste\n+ 4 Mastery\nClasses: Death Knight\nEquip: Increases the duration of Anti-Magic Shell by 100% and any damage it absorbs heals you.\n\"For you do not face me alone, but the host of the Ebon Blade itself. We are undying, we are unceasing, and we hunger for life!\"\nSell Price:" }
entries[132377] = { ["name"] = "Ariden's Compass", ["text"] = "Quest Item\n\"A battered old compass with ties to the Dark Riders of Deadwind Pass.\"" }
entries[132378] = { ["name"] = "Sacrolash's Dark Strike", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 7 Critical Strike\n+ 7 Mastery\n\nPrismatic Socket\n\nClasses: Warlock\nEquip: Corruption deals 15% increased damage and slows enemy movement speed by 60%.\n\"Misery... confusion... mistrust. These are the hallmarks.\"\nSell Price:" }
entries[132379] = { ["name"] = "Sin'dorei Spite", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Haste\nDurability 70 / 70\nClasses: Warlock\nEquip: For 25 sec after casting Summon Doomguard, Summon Infernal, or Summon Demonic Tyrant, you and your minions deal 15% increased damage. [ Grimoire of Supremacy : This effect can be gained only once every 3 min ]\n\"So many of our people have been twisted and dominated by the Burning Legion. It's only fitting that we in turn use their own armies against them.\"\nSell Price:" }
entries[132381] = { ["name"] = "Streten's Sleepless Shackles", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 3 Haste\n+ 2 Mastery\nDurability 70 / 70\nClasses: Warlock\nEquip: Each enemy afflicted with your Unstable Affliction increases all damage you deal by 4%.\n\"The only risk is that you'll go insane.\"\nSell Price:" }
entries[132393] = { ["name"] = "Recurrent Ritual", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Mastery\nDurability 120 / 120\nClasses: Warlock\nEquip: Call Dreadstalkers refunds 1 Soul Shard.\n\"It was always a wonder to outsiders how certain Vrykul warlocks managed to summon and command enormous packs of felstalkers.\"\nSell Price:" }
entries[132394] = { ["name"] = "Hood of Eternal Disdain", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 4 Critical Strike\n+ 6 Mastery\nDurability 120 / 120\nClasses: Warlock\nEquip: Agony deals its full damage 10% faster.\n\"Whoever dons this hood gains unholy strength and resolve, but will forever lose all kindness and compassion. Beware...\"\nSell Price:" }
entries[132404] = { ["name"] = "Package 5 - Water 1", ["text"] = "Binds when picked up\nSell Price:" }
entries[132406] = { ["name"] = "Marquee Bindings of the Sun King", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Haste\nDurability 70 / 70\nClasses: Mage\nEquip: After consuming Hot Streak, there is a 15% chance that your next non-instant Pyroblast cast within 15 sec deals 300% additional damage.\n\"Contrary to popular belief, Kael'thas's favored, and usually final, utterance to his enemies was actually 'PYROBLAST!'.\"\nSell Price:" }
entries[132407] = { ["name"] = "Magistrike Restraints", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Mastery\nDurability 70 / 70\nClasses: Warlock\nEquip: Chaos Bolt has a 20% chance to strike an additional enemy within 30 yards. (Proc chance: 20%)\n\"Varo'then was madly in love with the queen. Unfortunately, he never had the opportunity to use these restraints on her.\"\nSell Price:" }
entries[132409] = { ["name"] = "Anund's Seared Shackles", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Mastery\nDurability 70 / 70\nClasses: Priest\nEquip: Each time Shadow Word: Pain and Vampiric Touch deal damage, your next Void Bolt gains 3% increased damage, stacking up to 50 times.\n\"Why Anund was standing in front of Kaldrigos is anyone's guess. However, legend has it that Anund's final Shadow Word: Pain was key in helping Korl defeat the dread wyrm.\"\nSell Price:" }
entries[132410] = { ["name"] = "Shard of the Exodar", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Critical Strike\n+ 5 Haste\n\nPrismatic Socket\n\nClasses: Mage\nEquip: Your Time Warp does not cause Temporal Displacement on yourself and is not affected by Temporal Displacement or similar effects on yourself.\n\"The draenei capital city is able to transcend dimensions and even warp time itself. What could a sliver of its power do in the hands of a mere mortal?\"\nSell Price:" }
entries[132411] = { ["name"] = "Lady Vashj's Grasp", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHands Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Mastery\nDurability 70 / 70\nClasses: Mage\nEquip: While Icy Veins is active, you gain 1 charge of Fingers of Frost every 10 sec.\n\"Imbued with the power of the naga sea witch, your fingers inside feel frigid but surprisingly limber and highly energized.\"\nSell Price:" }
entries[132413] = { ["name"] = "Rhonin's Assaulting Armwraps", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 2 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Mage\nEquip: Arcane Missiles has a 18% chance to make your next Arcane Blast cast within 6 sec cost no mana. (Proc chance: 18%)\n\"Mages who wield as much power as Rhonin, a former leader of the Kirin Tor, often use arcane bindings to steady the magic unleashing from their fingertips.\"\nSell Price:" }
entries[132425] = { ["name"] = "Package 2 - Holy 1", ["text"] = "Binds when picked up\nSell Price:" }
entries[132436] = { ["name"] = "Skjoldr, Sanctuary of Ivagont", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 4 Haste\n+ 2 Mastery\nDurability 70 / 70\nClasses: Priest\nEquip: Your Power Word: Shield absorbs 15% more and reduces the remaining cooldown on Pain Suppression by 4 sec.\n\"Ivagont fought at Kakushan's side, as he always does, during their massacre of the Stormscale naga in Darkshore. By virtue of his protection, they left unscathed.\"\nSell Price:" }
entries[132437] = { ["name"] = "Mother Shahraz's Seduction", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nShoulder Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Mastery\nDurability 120 / 120\nClasses: Priest\nEquip: You gain 3 stacks of Voidform when you enter Voidform.\n\"You seem a little tense...\"\nSell Price:" }
entries[132438] = { ["name"] = "Talisman of Ascension", ["text"] = "Quest Item\n\"(NYI - Requires Revered with Valkyra) Given to Valkyra who have proven themselves ready to ascend to the highest ranks of their order.\"\nSell Price:" }
entries[132440] = { ["name"] = "The Svalnguard", ["text"] = "Quest Item\n\"Greatshield of Odyn, lord of the Halls of Valor.\"" }
entries[132441] = { ["name"] = "Draugr, Girdle of the Everlasting King", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Plate\n10 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 5 Haste\n+ 3 Mastery\nDurability 70 / 70\nClasses: Death Knight\nEquip: Festering Strike has a 30% chance to refund 1 rune. (Proc chance: 30%)\n\"Legend holds that the bodies of the titanspawn are so saturated with the energy of the creators that they leave behind fragments when the mortal host dies. This girdle is said to have been painstakingly sewn together from those fragments.\"\nSell Price:" }
entries[132442] = { ["name"] = "Cord of Infinity", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Mastery\nDurability 70 / 70\nClasses: Mage\nEquip: Increases damage done by Arcane Missiles by 10%.\nEquip: Each time Arcane Missiles hits an enemy, the damage of your next Mark of Aluneth is increased by 1.0%. This effect stacks.\n\"The magic contained inside seems to be as endless as the Burning Legion.\"\nSell Price:" }
entries[132443] = { ["name"] = "Aggramar's Stride", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Plate\n11 Armor\n+4 [Strength or Intellect]\n+6 Stamina\n+ 3 Critical Strike\n+ 3 Haste\n+ 5 Mastery\nDurability 95 / 95\nClasses: Warrior , Paladin , Death Knight\nEquip: Increases your movement speed by 75% of your Haste, Critical Strike, Mastery, or Versatility, whichever is highest.\n\"Time and space are one. To a watcher of the universe, distance is nearly meaningless.\"\nSell Price:" }
entries[132444] = { ["name"] = "Prydaz, Xavaric's Magnum Opus", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nNeck\n+4 Stamina\n+ 6 Critical Strike\n+ 6 Haste\n+ 6 Mastery\n\nPrismatic Socket\nEquip: Every 30 sec, gain an absorb shield for 25% of your maximum health for 30 sec.\n\"Bearers of this amulet whistle a haunting tune, and those nearby attest to a distant cry of anguish between the notes.\"\nSell Price:" }
entries[132445] = { ["name"] = "Al'maiesh, the Cord of Hope", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 3 Haste\n+ 5 Mastery\nDurability 70 / 70\nClasses: Priest\nEquip: If Serendipity is triggered and the Holy Word is not on cooldown, Serendipity increases the damage and healing of your next cast of that Holy Word by 10%, stacking up to 5 times.\n\"It is said that this once belonged to the original Val'kyr.\"\nSell Price:" }
entries[132446] = { ["name"] = "Jabrul's Jewels", ["text"] = "Quest Item\n\"A large sack containing various jewels.\"" }
entries[132447] = { ["name"] = "Entrancing Trousers of An'juna", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Haste\n+ 4 Mastery\nDurability 145 / 145\nClasses: Priest\nEquip: Increases the duration of Renew by 6 sec.\n\"Bearers of these trousers often go above and beyond the call of duty.\"\nSell Price:" }
entries[132448] = { ["name"] = "The Instructor's Fourth Lesson", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Plate\n9 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 4 Critical Strike\n+ 2 Haste\nDurability 70 / 70\nClasses: Death Knight\nEquip: Scourge Strike has a chance to burst an additional 1-2 Festering Wounds.\n\"Thought to be given by Razuvious to his most gifted acolytes, it is unclear how this band escaped the walls of Naxxramas. Could the Lich King have sent his own agents to the Broken Isles?\"\nSell Price:" }
entries[132449] = { ["name"] = "Phyrix's Embrace", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Haste\n+ 5 Mastery\n\nPrismatic Socket\n\nClasses: Priest\nEquip: Increases Guardian Spirit's duration and healing bonus by 50% and Guardian Spirit no longer terminates its healing bonus effect when sacrificing itself.\n\"Phyrix was a legendary priest who led adventurers through Molten Core and Blackwing Lair. She met an unfortunate demise at the hands of Nefarian, but her spirit still protects Azeroth's champions to this day.\"\nSell Price:" }
entries[132450] = { ["name"] = "Muze's Unwavering Will", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Cloth\n2 Armor\n+3 Intellect\n+4 Stamina\n+ 2 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Priest\nEquip: While above 75% health, the cast times of your Flash Heal, Heal, Prayer of Healing, and Smite are reduced by 15%.\n\"From their humble beginnings in Silvermoon to the depths of Blackrock Mountain, Muze always remained steadfast, faithfully healing her companions and saving them from the brinks of death.\"\nSell Price:" }
entries[132451] = { ["name"] = "Mystic Kilt of the Rune Master", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Haste\n+ 4 Mastery\nDurability 145 / 145\nClasses: Mage\nEquip: Arcane Barrage grants you 3% of your maximum mana per Arcane Charge spent.\n\"While Northrend's half-giants naturally know little to no magic, the mystic vrykul of Stormheim are masters of rune magic.\"\nSell Price:" }
entries[132452] = { ["name"] = "Sephuz's Secret", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 10 Critical Strike\n+ 4 Haste\n\nPrismatic Socket\nEquip: Gain 10% increased movement speed and 2% Haste. Successfully applying a loss of control effect to an enemy, interrupting an enemy, or dispelling any target increases this effect to 70% increased movement speed and 25% Haste for 10 sec. This increase may occur once every 30 sec.\n\"Intangibility is a curious concept. The word suggests some magical ability, but in the physical world, it simply means the power to be here or there, now or later.\"\nSell Price:" }
entries[132453] = { ["name"] = "Rattlegore Bone Legplates", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nLegs Plate\n16 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 4 Haste\n+ 6 Mastery\nDurability 145 / 145\nClasses: Death Knight\nEquip: Bone Shield grants an additional 10% armor and increases your maximum Runic Power by 60.\n\"Parts of the shambling horror Rattlegore still contain potent necromantic energies that respond to the will of those strong enough to command them.\"\nSell Price:" }
entries[132454] = { ["name"] = "Koralon's Burning Touch", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Critical Strike\n+ 3 Haste\nDurability 70 / 70\nClasses: Mage\nEquip: Scorch deals 350% increased damage and is a guaranteed Critical Strike against enemies below 30% health.\n\"Deep within the vault protected by Wintergrasp, Koralon the Flame Watcher was furious when intruders entered.\"\nSell Price:" }
entries[132455] = { ["name"] = "Norgannon's Foresight", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nFeet Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 3 Critical Strike\n+ 4 Haste\n+ 3 Mastery\nDurability 95 / 95\nClasses: Priest , Mage , Warlock\nEquip: Standing still for 6 sec grants you Foresight, allowing you to cast while moving for 4 sec. This duration begins when you start moving.\n\"Magic must be regulated, managed, and controlled. But it must also be appreciated and valued, not hoarded. Such is the paradox that you must comprehend.\"\nSell Price:" }
entries[132456] = { ["name"] = "Feretory of Souls", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 4 Haste\n+ 3 Mastery\nDurability 70 / 70\nClasses: Warlock\nEquip: Casting a damaging Fire spell has a 6% chance to generate a Soul Shard. (Proc chance: 6%)\n\"Viewed from different angles, there seems to be faint reflection of three different faces.\"\nSell Price:" }
entries[132457] = { ["name"] = "Power Cord of Lethtendris", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 3 Critical Strike\n+ 5 Haste\nDurability 70 / 70\nClasses: Warlock\nEquip: Casting Unstable Affliction on a target who is not already affected by Unstable Affliction has a 25% chance to refund the Soul Shard cost.\n\"Lethtendris constructed a device to siphon Dire Maul's overwhelming corrupt power for herself.\"\nSell Price:" }
entries[132458] = { ["name"] = "Toravon's Whiteout Bindings", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWrist Plate\n9 Armor\n+3 [Strength or Intellect]\n+4 Stamina\n+ 3 Haste\n+ 2 Mastery\nDurability 70 / 70\nClasses: Death Knight\nEquip: While Pillar of Frost is active, you deal 15% increased Frost damage.\n\"Deep within the vault protected by Wintergrasp, Toravon the Ice Watcher was relentless in smashing interlopers.\"\nSell Price:" }
entries[132459] = { ["name"] = "Perseverance of the Ebon Martyr", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Plate\n13 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 6 Haste\n+ 4 Mastery\nDurability 120 / 120\nClasses: Death Knight\nEquip: Howling Blast deals 20% increased damage to enemies recently damaged by your Remorseless Winter.\n\"Cold steel rests heavily on the brow of this crown's bearer.\"\nSell Price:" }
entries[132460] = { ["name"] = "Alythess's Pyrogenics", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Haste\n\nPrismatic Socket\n\nClasses: Warlock\nEquip: Enemies affected by your Rain of Fire take 10% increased damage from your Fire spells.\n\"Depravity... hatred... chaos. These are the pillars.\"\nSell Price:" }
