entries[132861] = { ["name"] = "Estel, Dejahna's Inspiration", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Cloth\n5 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Mastery\nDurability 200 / 200\nClasses: Priest\nEquip: Increases healing done by 3%.\nEquip: Plea increases your Haste by 1% for each target with your Atonement for 8 sec.\n\"Faith is the beginning of all things. If your skill with the arcane is passable, but not strong, you may still become a sorceress. But if your faith is only passable and not strong, you will never become a priestess.\"\nSell Price:" }
entries[132862] = { ["name"] = "Ring of the Fallen", ["text"] = "Quest Item\n\"Set upon the top of the ring is a black opal, with a swirling mist that resembles something akin to a soul.\"" }
entries[132863] = { ["name"] = "Darckli's Dragonfire Diadem", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Haste\nDurability 120 / 120\nClasses: Mage\nEquip: Increases Dragon's Breath's damage by 100% and range by 25 yards.\n\"Among Archmage Darckli's innumerable achievements was mastering the art of breathing dragonfire directly from his mouth.\"\nSell Price:" }
